# Generated by `bun run generate:packaging 0.10.0`.
# Downloads the official per-machine MSI from the GitHub release.
$ErrorActionPreference = 'Stop'

if (-not [Environment]::Is64BitOperatingSystem) {
  throw 'Typsastra requires a 64-bit version of Windows.'
}

$isArm64 = $env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or $env:PROCESSOR_ARCHITEW6432 -eq 'ARM64'
$url = if ($isArm64) { 'https://github.com/Sovichea/typsastra/releases/download/v0.10.0/Typsastra_0.10.0_arm64_en-US.msi' } else { 'https://github.com/Sovichea/typsastra/releases/download/v0.10.0/Typsastra_0.10.0_x64_en-US.msi' }
$checksum = if ($isArm64) { 'fbc015bfabb64cfa01126ee6e871b34e0eac08e5803bee68ae118533d3e299f3' } else { '1fa1c06786543ce1b135fe53b7cba5679c8c1bef193bfa5f864c5dbdd7a143b2' }

$packageArgs = @{
  packageName    = $env:ChocolateyPackageName
  fileType       = 'msi'
  url64bit       = $url
  checksum64     = $checksum
  checksumType64 = 'sha256'
  silentArgs     = '/quiet /norestart'
  validExitCodes = @(0, 3010, 1641)
  softwareName   = 'Typsastra'
}

Install-ChocolateyPackage @packageArgs
